const row = $json;

const text = [
  'search_document: Земельный участок',
  `Кадастровый номер: ${row.cadastral_number ?? 'не указан'}`,
  `Координаты: ${row.coordinates ?? 'не указан'}`,
  `Адрес: ${row.address ?? 'не указан'}`,
  `Тип аукциона: ${row.auction_type ?? 'не указан'}`,
  `Категория земли: ${row.land_category ?? 'не указана'}`,
  `Разрешенное использование: ${row.permitted_use ?? 'не указано'}`,
  `Площадь: ${row.area_m2 ?? 'не указана'}`,
  `Начальная цена: ${row.start_price ?? 'не указана'}`,
  `Дата окончания приема заявок: ${row.application_deadline ?? 'отсутствует'}`,
].join('\n');

return {
  json: {
    ...row,
    lot_id: String(row.id),
    pageContent: text,
  },
};
